This is a sample script for notifying the new release of Google APIs and Google Apps Script with an email using Google Apps Script.
Recently, I published a sample script of &ldquo;Retrieving Release Notes of Google Apps Script and Google APIs from RSS using Google Apps Script&rdquo;. After this was published, I got an email that it wants to automatically notice the new release of Google APIs and Google Apps Script with an email. From this, I prepared a sample script as follows.
Sample script Please set your email address to email in main. When you use this script, please manually run main function. By this, at 1st run, the new release in one month is checked as a test. And, the current date is stored in the PropertiesService. When you want to automatically obtain the notification, please install the time-driven trigger to main. For example, I run main one time at 00:00-01:00 every day. By this, when the new release is added, the email can be received.
// ref: https://tanaikech.github.io/2023/06/17/retrieving-release-notes-of-google-apps-script-and-google-apis-from-rss-using-google-apps-script/ const sendEmail_ = (obj) =&gt; MailApp.sendEmail(obj); function getData_({ urls, checkDate }) { const reqs = urls.map((url) =&gt; ({ url, muteHttpExceptions: true })); const res = UrlFetchApp.fetchAll(reqs); const values = res.reduce((ar, r) =&gt; { if (r.getResponseCode() == 200) { const xml = XmlService.parse(r.getContentText()); const root = xml.getRootElement(); const ns = root.getNamespace(); const updated = new Date(root.getChild(&#34;updated&#34;, ns).getValue()); if (updated.getTime() &gt; checkDate) { const title = root.getChild(&#34;title&#34;, ns).getValue(); const entries = root.getChildren(&#34;entry&#34;, ns).map((e) =&gt; { const updated = new Date(e.getChild(&#34;updated&#34;, ns).getValue()); const href = e.getChild(&#34;link&#34;, ns).getAttribute(&#34;href&#34;).getValue(); const content = e.getChild(&#34;content&#34;, ns).getValue().trim(); return [updated, href, content]; }); ar = [...ar, ...entries.map((e) =&gt; [title, updated, ...e])]; } } return ar; }, []); return values; } // Please run this function. function main() { const email = &#34;###&#34;; // Please set your email address. The message is sent to the email. try { const urls = [ &#34;https://developers.google.com/feeds/apps-script-release-notes.xml&#34;, &#34;https://developers.google.com/feeds/drive-release-notes.xml&#34;, &#34;https://developers.google.com/feeds/sheets-release-notes.xml&#34;, &#34;https://developers.google.com/feeds/docs-release-notes.xml&#34;, &#34;https://developers.google.com/feeds/slides-release-notes.xml&#34;, &#34;https://developers.google.com/feeds/forms-release-notes.xml&#34;, &#34;https://developers.google.com/feeds/calendar-release-notes.xml&#34;, &#34;https://developers.google.com/feeds/gmail-release-notes.xml&#34;, ]; const prop = PropertiesService.getScriptProperties(); const checkDate = ((prop) =&gt; { const k = prop.getProperty(&#34;checkDate&#34;); if (!k) { const d = new Date(); d.setMonth(d.getMonth() - 1); return d.getTime(); } return new Date(k).getTime(); })(prop); const values = getData_({ urls, checkDate }); if (values.length &gt; 0) { sendEmail_({ to: email, subject: &#34;Update release note.&#34;, body: JSON.stringify(values, null, 2), }); } prop.setProperty(&#34;checkDate&#34;, new Date().toISOString()); } catch (e) { sendEmail_({ to: email, subject: &#34;Error from Update release note.&#34;, body: JSON.stringify(e, null, 2), }); } }

