These are the sample scripts for uploading files of multipart/form-data to Google Drive using Drive API with Node.js. In this case, googleapis for Node.js is not used.
In these sample script, the maximum file size is 5 MB. Please be careful this. When you want to upload the files more than 5 MB, please check this report.
Sample script 1 This sample script uploads a file using the modules of fs and request. Before you use this script, please prepare your access token for uploading the file.
const fs = require(&#34;fs&#34;); const request = require(&#34;request&#34;); const filePath = &#34;./sample.txt&#34;; const accessToken = &#34;###&#34;; fs.readFile(filePath, function (err, content) { if (err) { console.error(err); } const metadata = { name: &#34;sample.txt&#34;, }; const boundary = &#34;xxxxxxxxxx&#34;; let data = &#34;--&#34; + boundary + &#34;
&#34;; data += &#39;Content-Disposition: form-data; name=&#34;metadata&#34;
&#39;; data += &#34;Content-Type: application/json; charset=UTF-8

&#34;; data += JSON.stringify(metadata) + &#34;
&#34;; data += &#34;--&#34; + boundary + &#34;
&#34;; data += &#39;Content-Disposition: form-data; name=&#34;file&#34;

&#39;; const payload = Buffer.concat([ Buffer.from(data, &#34;utf8&#34;), Buffer.from(content, &#34;binary&#34;), Buffer.from(&#34;
--&#34; + boundary + &#34;--
&#34;, &#34;utf8&#34;), ]); request( { method: &#34;POST&#34;, url: &#34;https://www.googleapis.com/upload/drive/v3/files?uploadType=multipart&#34;, headers: { Authorization: &#34;Bearer &#34; + accessToken, &#34;Content-Type&#34;: &#34;multipart/form-data; boundary=&#34; + boundary, }, body: payload, }, (err, res, body) =&gt; { if (err) { console.log(body); return; } console.log(body); } ); }); Sample script 2 This sample script uploads a file using the modules of fs, form-data and node-fetch. Before you use this script, please prepare your access token for uploading the file.
const fs = require(&#34;fs&#34;); const FormData = require(&#34;form-data&#34;); const fetch = require(&#34;node-fetch&#34;); const filePath = &#34;./sample.txt&#34;; const accessToken = &#34;###&#34;; token = req.body.token; var formData = new FormData(); var fileMetadata = { name: &#34;sample.txt&#34;, }; formData.append(&#34;metadata&#34;, JSON.stringify(fileMetadata), { contentType: &#34;application/json&#34;, }); formData.append(&#34;data&#34;, fs.createReadStream(filePath), { filename: &#34;sample.txt&#34;, contentType: &#34;text/plain&#34;, }); fetch(&#34;https://www.googleapis.com/upload/drive/v3/files?uploadType=multipart&#34;, { method: &#34;POST&#34;, body: formData, headers: { Authorization: &#34;Bearer &#34; + accessToken }, }) .then((res) =&gt; res.json()) .then(console.log); Result When above scripts are run, the following result is retrieved from both scripts.
{ &#34;kind&#34;: &#34;drive#file&#34;, &#34;id&#34;: &#34;###&#34;, &#34;name&#34;: &#34;sample.txt&#34;, &#34;mimeType&#34;: &#34;text/plain&#34; } Reference Upload file data

