This is a sample Node.js script to retrieve access token from Service Account of Google without using googleapis.
const cryptor = require(&#39;crypto&#39;); const request = require(&#39;request&#39;); const privateKey = &#34;###&#34;; // private_key of JSON file retrieved by creating Service Account const clientEmail = &#34;###&#34;; // client_email of JSON file retrieved by creating Service Account const scopes = [&#34;https://www.googleapis.com/auth/drive.readonly&#34;]; // Sample scope const url = &#34;https://www.googleapis.com/oauth2/v4/token&#34;; const header = { alg: &#34;RS256&#34;, typ: &#34;JWT&#34;, }; const now = Math.floor(Date.now() / 1000); const claim = { iss: clientEmail, scope: scopes.join(&#34; &#34;), aud: url, exp: (now + 3600).toString(), iat: now.toString(), }; const signature = Buffer.from(JSON.stringify(header)).toString(&#39;base64&#39;) + &#34;.&#34; + Buffer.from(JSON.stringify(claim)).toString(&#39;base64&#39;); var sign = cryptor.createSign(&#39;RSA-SHA256&#39;); sign.update(signature); const jwt = signature + &#34;.&#34; + sign.sign(privateKey, &#39;base64&#39;); request({ method: &#34;post&#34;, url: url, body: JSON.stringify({ assertion: jwt, grant_type: &#34;urn:ietf:params:oauth:grant-type:jwt-bearer&#34;, }), }, (err, res, body) =&gt; { if (err) { console.log(err); return; } console.log(body); });

