Create New Spreadsheet using Text Value const request = require(&#39;request&#39;); const textData = &#34;a1, b1, c1, d1, e1&#34;; // This is used as CSV data. const orgMimeType = &#34;text/csv&#34;; const orgFileName = &#34;sample.csv&#34;; const accessToken = &#34;###&#34;; // Access token const metadata = { name: &#34;convertedSampleCSV&#34;, mimeType: &#34;application/vnd.google-apps.spreadsheet&#34;, }; const url = &#34;https://www.googleapis.com/upload/drive/v3/files?uploadType=multipart&#34;; const boundary = &#34;xxxxxxxxxxx&#34;; var data = &#34;--&#34; + boundary + &#34;
&#34;; data += &#34;Content-Disposition: form-data; name=\&#34;metadata\&#34;
