--&#34; + boundary + &#34;--&#34;, &#34;utf8&#34;), ]); const options = { method: &#39;post&#39;, url: url, headers: { &#34;Content-Type&#34;: &#34;multipart/related; boundary=&#34; + boundary, &#39;Authorization&#39;: &#39;Bearer &#39; + accessToken, }, body: payload, }; request(options, (error, response, body) =&gt; { console.log(body); }); Overwrite Existing Google Document using Text Value This can be used when you don&rsquo;t want to update the existing Google Docs without changing the file ID.

