This is a sample script which works the same action with the CLEAN method of VBA. The CLEAN method of VBA removes the characters of 0-31, 127, 129, 141, 143, 144, 157. Although I had looked for such method for Google Apps Script, I couldn&rsquo;t find it. So I created this. If this is useful for you, I&rsquo;m glad.
function cleanForGAS(str) { if (typeof str == &#34;string&#34;) { var escaped = escape(str.trim()); for (var i = 0; i &lt;= 31; i++) { var s = i.toString(16); var re = new RegExp(&#34;%&#34; + (s.length == 1 ? &#34;0&#34; + s : s).toUpperCase(), &#34;g&#34;); escaped = escaped.replace(re, &#34;&#34;); } var remove = [&#34;%7F&#34;, &#34;%81&#34;, &#34;%8D&#34;, &#34;%8F&#34;, &#34;%90&#34;, &#34;%9D&#34;]; remove.forEach(function(e) { var re = new RegExp(e, &#34;g&#34;); escaped = escaped.replace(re, &#34;&#34;); }); return unescape(escaped).trim(); } else { return str; } } function main() { var res = cleanForGAS(str); }

