This sample script is for the interconversion between Google Docs (document, spreadsheet and presentation) and Microsoft Docs (word, excel and powerpoint). The feature is to convert them without Advanced Google Services.
Since Advanced Google Services is not used for this, if you publish your script with this script, you are not necessary to explain how to install Advanced Google Services. This script converts between Google Docs and Microsoft Docs using UrlFetchApp.fetch(). Although Drive API v3 is used, Drive API is automatically enabled by the recent update on Google. Ref (I&rsquo;m sorry. This is Japanese language.) So you are not necessary to explain about the use of Drive API. By this, users will be easy to use the scripts that Drive API is used. This is very important for a lot of users.
Script In order to use both script, please give file ID to each method. Each method creates the converted file and return the created file ID.
If you want to give the file ID from the filename, please use following sample.
var filename = &#34;sample&#34;; var fileId = DriveApp.getFilesByName(filename).next().getId(); From Google Docs to Microsoft Docs function convToMicrosoft(fileId) { if (fileId == null) throw new Error(&#34;No file ID.&#34;); var file = DriveApp.getFileById(fileId); var mime = file.getMimeType(); var format = &#34;&#34;; var ext = &#34;&#34;; switch (mime) { case &#34;application/vnd.google-apps.document&#34;: format = &#34;application/vnd.openxmlformats-officedocument.wordprocessingml.document&#34;; ext = &#34;.docx&#34;; break; case &#34;application/vnd.google-apps.spreadsheet&#34;: format = &#34;application/vnd.openxmlformats-officedocument.spreadsheetml.sheet&#34;; ext = &#34;.xlsx&#34;; break; case &#34;application/vnd.google-apps.presentation&#34;: format = &#34;application/vnd.openxmlformats-officedocument.presentationml.presentation&#34;; ext = &#34;.pptx&#34;; break; default: return null; } var url = &#34;https://www.googleapis.com/drive/v3/files/&#34; + fileId + &#34;/export?mimeType=&#34; + format; var blob = UrlFetchApp.fetch(url, { method: &#34;get&#34;, headers: {&#34;Authorization&#34;: &#34;Bearer &#34; + ScriptApp.getOAuthToken()}, muteHttpExceptions: true }).getBlob(); var filename = file.getName(); var id = DriveApp.createFile(blob).setName(~filename.indexOf(ext) ? filename : filename + ext).getId(); return id; }; From Microsoft Docs to Google Docs Here, Multipart-POST Request Using Google Apps Script was used for using Drive File Create.
function convToGoogle(fileId) { if (fileId == null) throw new Error(&#34;No file ID.&#34;); var file = DriveApp.getFileById(fileId); var filename = file.getName(); var mime = file.getMimeType(); var ToMime = &#34;&#34;; switch (mime) { case &#34;application/vnd.openxmlformats-officedocument.wordprocessingml.document&#34;: ToMime = &#34;application/vnd.google-apps.document&#34;; break; case &#34;application/vnd.openxmlformats-officedocument.spreadsheetml.sheet&#34;: ToMime = &#34;application/vnd.google-apps.spreadsheet&#34;; break; case &#34;application/vnd.openxmlformats-officedocument.presentationml.presentation&#34;: ToMime = &#34;application/vnd.google-apps.presentation&#34;; break; default: return null; } var metadata = { name: filename, mimeType: ToMime }; var fields = &#34;id,mimeType,name&#34;; var url = &#34;https://www.googleapis.com/upload/drive/v3/files?uploadType=multipart&amp;fields=&#34; + encodeURIComponent(fields); var boundary = &#34;xxxxxxxxxx&#34;; var data = &#34;--&#34; + boundary + &#34;
&#34;; data += &#34;Content-Type: application/json; charset=UTF-8

&#34;; data += JSON.stringify(metadata) + &#34;
&#34;; data += &#34;--&#34; + boundary + &#34;
&#34;; data += &#34;Content-Type: &#34; + mime + &#34;

&#34;; var payload = Utilities.newBlob(data).getBytes().concat(file.getBlob().getBytes()).concat(Utilities.newBlob(&#34;
--&#34; + boundary + &#34;--&#34;).getBytes()); var res = UrlFetchApp.fetch(url, { method: &#34;post&#34;, headers: { &#34;Authorization&#34;: &#34;Bearer &#34; + ScriptApp.getOAuthToken(), &#34;Content-Type&#34;: &#34;multipart/related; boundary=&#34; + boundary }, payload: payload, muteHttpExceptions: true }).getContentText(); var id = JSON.parse(res).id; return id; };

